#include <iostream>

class Account {
    int balance_;
public:
    explicit Account(int initial) : balance_{initial < 0 ? 0 : initial} {}
    void deposit(int amount) { if (amount > 0) balance_ += amount; }
    int balance() const { return balance_; }
};

int main() {
    Account wallet{20};
    wallet.deposit(5);
    std::cout << wallet.balance() << "\n";
}

#include <iostream>

struct Shape {
    virtual int area() const = 0;
    virtual ~Shape() = default;
};
struct Square : Shape {
    int side;
    explicit Square(int s) : side{s} {}
    int area() const override { return side * side; }
};

int main() {
    Square square{4};
    const Shape& shape = square;
    std::cout << shape.area() << "\n";
}

