#include <iostream>

template <typename T>
constexpr T square(T value) {
    return value * value;
}

int main() {
    constexpr int size = square(4);
    static_assert(size == 16, "unexpected size");
    double value{}; std::cin >> value;
    std::cout << square(value) << "\n";
}

#include <iostream>
#include <optional>

std::optional<int> divide(int a, int b) {
    if (b == 0) return std::nullopt;
    return a / b;
}

int main() {
    int a{}, b{}; std::cin >> a >> b;
    if (auto result = divide(a, b)) {
        std::cout << *result << "\n";
    } else {
        std::cout << "undefined\n";
    }
}
